class Kendaraan:
def info(self):
return "Kendaraan"
class Mobil(Kendaraan):
def info(self):
return "Mobil"
class Motor(Kendaraan):
def info(self):
return "Motor"
def tampil(obj):
return obj.info()
for item in [Kendaraan(), Mobil(), Motor()]:
print(tampil(item))
